script:
(function(){
  var body=document.getElementById('postBody');
  if(!body) return;
  var hs=body.querySelectorAll('h2,h3');
  if(hs.length<2) return;
  var toc=document.createElement('div');
  toc.id='post-toc';
  var title=document.createElement('div');
  title.id='post-toc-title';
  title.textContent='\u76EE\u5F55';
  toc.appendChild(title);
  var links=[];
  for(var i=0;i<hs.length;i++){
    var h=hs[i];
    var id='toc-'+i;
    h.id=id;
    var a=document.createElement('a');
    a.href='#'+id;
    a.textContent=h.textContent;
    a.className=h.tagName==='H3'?'toc-h3':'';
    toc.appendChild(a);
    links.push({el:a,target:h});
  }
  body.parentNode.insertBefore(toc,body);
  window.addEventListener('scroll',function(){
    var scrollY=window.scrollY+120;
    var current=null;
    for(var j=0;j<links.length;j++){
      if(links[j].target.offsetTop<=scrollY) current=j;
    }
    for(var k=0;k<links.length;k++){
      links[k].el.className=(k===current)?(links[k].target.tagName==='H3'?'toc-h3 active':'active'):(links[k].target.tagName==='H3'?'toc-h3':'');
    }
  });
})();

